from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];s=json.loads((R/'reports/v132/packed_validation_summary.json').read_text(encoding='utf-8'));assert s['passed']
n=s['transport']['summary']['transport_noise'];c=s['station'];a=s['identity']
rows=''.join(f"<tr><td>{name}</td><td>{v['raw']['request_ms']:.2f}</td><td>{v['legacy']['request_ms']:.2f}</td><td>{v['compact']['request_ms']:.2f}</td><td>{v['compact']['wire_saving_percent']:.4f}%</td></tr>" for name,v in s['transport']['summary'].items())
html=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TileLab V1.25 实板验证</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#edf4f4;color:#173e47;font:16px/1.8 system-ui}}main{{max-width:1050px;margin:30px auto;padding:30px;background:white;border-radius:18px}}a{{color:#087d80}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}}.metric{{background:#edf6f5;border-radius:12px;padding:18px}}.metric b{{display:block;font-size:28px}}.note{{background:#fff0df;padding:18px;border-left:4px solid #ba772c}}h1{{font-size:32px}}table{{width:100%;border-collapse:collapse}}td,th{{padding:10px;border-bottom:1px solid #d5e4e6;text-align:left}}small{{color:#55767c}}@media(max-width:700px){{.grid{{grid-template-columns:1fr}}main{{margin:0;padding:20px}}}}</style><main><a href="/">← 返回检测工作台</a><p>V1.25 · 实板逐项验收完成</p><h1>完整原图，掩码按位无损传输</h1><p>保留 V1.24 检测硬件、74.25 MHz 和 720p60。FPGA 执行检测与最佳图选择；ARM 只做格式转换和传输。</p><div class="grid"><div class="metric">难压缩画面负载减少<b>21.875%</b><small>3,686,400 → 2,880,000 字节</small></div><div class="metric">三种格式逐字节相同<b>50 组 / 150 次</b><small>RAW32 / WORD_RLE / 可选位打包</small></div><div class="metric">真实故障与恢复<b>13 类网络故障</b><small>另含实际 DDR 位翻转、3 类重启</small></div></div>
<h2>默认优先延迟，省流由你选择</h2><div class="note">难压缩画面请求中位数：旧自适应 {n['legacy']['request_ms']:.2f} ms，省流模式 {n['compact']['request_ms']:.2f} ms。当前先整帧编码再发送，省字节但增加等待。默认继续使用较快的旧自适应策略，界面提供明确的省流选项。</div>
<p>二值掩码原来占一个字节，现在每像素只传一位。颜色没有量化，像素没有缩小；电脑还原 BGRM32 后检查 FPGA 原始 CRC。WORD_RLE 更小的图仍继续使用游程压缩。</p><table><thead><tr><th>输入</th><th>RAW ms</th><th>旧自适应 ms</th><th>省流 ms</th><th>负载减少</th></tr></thead><tbody>{rows}</tbody></table><p>以上是本机请求中位数；不等同纯物理网线速度，也不意味着电脑预览达到 60 fps。</p>
<h2>可靠性与兼容性</h2><p>198 项主机测试、实际 C 编码器 294 组往返、574 容量/对齐边界、840 非法高位案例通过。20 类非法板端请求被拒绝。未修改的 V1.24 客户端实测仍正常。</p><p>颜色/掩码损坏不保存、不确认；中途断线重读同一事件；确认回复丢失不重复存图。实际修改锁定 DDR 截图的非法位，RAW 回退完整保留错误位，电脑 CRC 拒绝；恢复后原事件通过。3 类 PACK25 保存后重启场景保留 PNG 与复核备注。</p>
<h2>持续运动验收</h2><p>{c['seconds']:.2f} 秒接收 {c['host_captures']} 张抽样图，保存 {c['saved']} 个缺陷产品各一张最佳图；最大居中偏差 {a['max_center_error_px']} 像素。掩码和框逐像素对照通过，无新增采集/队列错误。日常默认仅预览，不无限保存截图。</p>
<div class="note"><strong>适用范围没有被传输优化扩大</strong><p>检测算法与 V1.24 相同。旧照片属于开发素材，跨材质正常屋面陶瓷误报仍高；没有真实相机、曝光和运动模糊验收。五个既有 CDC 不安全端点、有限 DDR 队列、未传出证据掉电丢失、HDMI 前一帧红框等限制仍然存在。</p></div><p><a href="/api/benchmark">完整实板验证 JSON</a> · 工程报告：docs/Tile_V1.25_无损位打包与实板报告.md</p></main></html>'''
(R/'host/benchmark.html').write_text(html,encoding='utf-8')
p=R/'README.md';t=p.read_text(encoding='utf-8').replace('本版实现及验收进行中，不能把建好目录视为完成。','本版已完成实现、构建和实板验收，最终源码/下载文件校验见 DELIVERY_MANIFEST.json。')
t=t.replace('实测速度是否改善仍待验证。','实测省流模式增加了编码等待，因此默认保持较快的旧自适应模式，省流模式明确可选。')
t+='\n完整报告：[V1.25 无损位打包与实板报告](docs/Tile_V1.25_无损位打包与实板报告.md)；学习说明：[无损位打包原理](docs/V1.25_无损位打包原理.md)。\n'
p.write_text(t,encoding='utf-8');print('Published verified V1.25 page with explicit bandwidth/latency tradeoff')
